package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.ToDoubleFunction;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.BinaryTupleOperator;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.QueryModelVisitor;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.UnaryTupleOperator;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.CascadesPlanner;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal;
import org.junit.jupiter.api.Test;

/**
 * Review reproducers for packed-search fail-safety and determinism (candidates 2 and 3). Every assertion states the
 * robust expectation; a failure demonstrates the finding.
 */
class PackedPlanningFailSafeReviewReproTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void singleFlightWaiterMustSeeTheSameFallbackableFailureAsTheOwner() {
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		PackedPlanCache.Context context = new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 11L);
		TupleExpr query = new Join(sp("a", "urn:p", "b"), sp("b", "urn:q", "c"));
		PackedPlanCache.Fingerprint fingerprint = cache.fingerprint(query);
		PackedPlanCache.FlightClaim owner = cache.beginFlight(fingerprint, context, query);
		PackedPlanCache.FlightClaim waiter = cache.beginFlight(fingerprint, context, query);
		assertTrue(owner.owner());
		assertFalse(waiter.owner());

		// The owner thread rethrows this IllegalStateException; LmdbCascadesOptimizer falls back on it.
		cache.fail(owner, new PackedMemoInvariantException("memo invariant breached during planning"));
		RuntimeException seenByWaiter = assertThrows(RuntimeException.class, waiter::await);
		assertTrue(seenByWaiter instanceof IllegalStateException,
				"a concurrent waiter observes " + seenByWaiter.getClass().getName()
						+ ", which LmdbCascadesOptimizer does not catch, so its query fails instead of falling back");
	}

	@Test
	void unsupportedOperatorMustSurfaceAsAFallbackableFailure() {
		TupleExpr query = new OpaqueTuple(new Join(sp("a", "urn:p", "b"), sp("b", "urn:q", "c")));
		RuntimeException failure = assertThrows(RuntimeException.class,
				() -> new CascadesPlanner().optimize(query, OptimizationGoal.root()));
		assertTrue(failure instanceof IllegalStateException,
				"planning failed with " + failure.getClass().getName()
						+ " (not an IllegalStateException) so LMDB would fail the query rather than fall back");
	}

	@Test
	void negativeProviderRowsMustBeTreatedLikeUnknownRows() {
		TupleExpr query = star();
		String withNaN = order(PackedCascadesPlanner.optimize(query.clone(), OptimizationGoal.root(),
				model(predicate -> predicate.equals("p1") ? Double.NaN : rowsFor(predicate, 100.0d)))
				.selectedPlan());
		PackedPlanningResult negative = PackedCascadesPlanner.optimize(query.clone(), OptimizationGoal.root(),
				model(predicate -> predicate.equals("p1") ? -1.0e9d : rowsFor(predicate, 100.0d)));
		String withNegative = order(negative.selectedPlan());
		assertTrue(Double.isFinite(negative.totalCost()) && negative.totalCost() >= 0.0d,
				"negative provider rows produced total cost " + negative.totalCost());
		assertEquals(withNaN, withNegative, "negative rows leaked into search (NaN plan=" + withNaN
				+ ", negative plan=" + withNegative + ", cost=" + negative.totalCost() + ")");
	}

	@Test
	void planChoiceMustNotDependOnQueryTextOrder() {
		Map<String, Integer> finite = distinctPlansAcrossInputOrders(1.0d, false);
		Map<String, Integer> finiteShape = distinctPlansAcrossInputOrders(1.0d, true);
		Map<String, Integer> saturated = distinctPlansAcrossInputOrders(1.0e200d, false);
		Map<String, Integer> saturatedShape = distinctPlansAcrossInputOrders(1.0e200d, true);
		String report = "finite=" + finite + " finiteShape=" + finiteShape + " saturated=" + saturated
				+ " saturatedShape=" + saturatedShape;
		assertEquals(1, saturatedShape.size(), "saturated costs change the join SHAPE with input order: " + report);
		assertEquals(1, finite.size(), "same query, 24 textual orders, several plans: " + report);
	}

	@Test
	void oneOversizedOptionalReservationMustNotExhaustTheRemainingBudget() {
		PackedSearchBudget budget = new PackedSearchBudget(1_000L, Long.MAX_VALUE);
		assertTrue(budget.tryReserve(10L));
		assertFalse(budget.tryReserve(5_000L), "an oversized optional block is refused");
		assertTrue(budget.tryReserve(1L) || budget.canReserveMandatoryCompletion(1L),
				"990 units remain but the budget latched workLimitReached after one refused optional block: used="
						+ budget.workUnits() + " workLimitReached=" + budget.workLimitReached());
	}

	// ---------------------------------------------------------------- helpers

	private static Map<String, Integer> distinctPlansAcrossInputOrders(double scale, boolean orientationInsensitive) {
		List<StatementPattern> factors = List.of(sp("s", "urn:p1", "o1"), sp("s", "urn:p2", "o2"),
				sp("s", "urn:p3", "o3"), sp("s", "urn:p4", "o4"));
		Map<String, Integer> plans = new TreeMap<>();
		for (List<StatementPattern> permutation : permutations(factors)) {
			TupleExpr query = leftDeep(permutation);
			PackedPlanningResult result = PackedCascadesPlanner.optimize(query, OptimizationGoal.root(),
					model(predicate -> rowsFor(predicate, 100.0d) * scale));
			String rendered = orientationInsensitive ? shape(result.selectedPlan()) : order(result.selectedPlan());
			plans.merge(rendered, 1, Integer::sum);
		}
		return plans;
	}

	private static double rowsFor(String predicate, double base) {
		return switch (predicate) {
		case "p1" -> base;
		case "p2" -> base * 2.0d;
		case "p3" -> base * 3.0d;
		case "p4" -> base * 4.0d;
		default -> Double.NaN;
		};
	}

	private static PackedCostModel model(ToDoubleFunction<String> rowsByPredicateLocalName) {
		return (query, relationId) -> {
			if (!query.isStatementPattern(relationId)) {
				return Double.NaN;
			}
			String predicate = query.statementPatternValue(relationId, 1).stringValue();
			return rowsByPredicateLocalName.applyAsDouble(predicate.substring("urn:".length()));
		};
	}

	private static TupleExpr star() {
		return leftDeep(List.of(sp("s", "urn:p1", "o1"), sp("s", "urn:p2", "o2"), sp("s", "urn:p3", "o3"),
				sp("s", "urn:p4", "o4")));
	}

	private static TupleExpr leftDeep(List<StatementPattern> factors) {
		TupleExpr result = factors.get(0).clone();
		for (int i = 1; i < factors.size(); i++) {
			result = new Join(result, factors.get(i).clone());
		}
		return result;
	}

	private static List<List<StatementPattern>> permutations(List<StatementPattern> values) {
		List<List<StatementPattern>> result = new ArrayList<>();
		permute(new ArrayList<>(values), 0, result);
		return result;
	}

	private static void permute(List<StatementPattern> values, int offset, List<List<StatementPattern>> result) {
		if (offset == values.size()) {
			result.add(List.copyOf(values));
			return;
		}
		for (int i = offset; i < values.size(); i++) {
			java.util.Collections.swap(values, offset, i);
			permute(values, offset + 1, result);
			java.util.Collections.swap(values, offset, i);
		}
	}

	private static String shape(TupleExpr expr) {
		if (expr instanceof BinaryTupleOperator binary) {
			String left = shape(binary.getLeftArg());
			String right = shape(binary.getRightArg());
			return expr.getClass().getSimpleName() + "{" + (left.compareTo(right) <= 0 ? left + "," + right
					: right + "," + left) + "}";
		}
		if (expr instanceof UnaryTupleOperator unary) {
			return expr.getClass().getSimpleName() + "[" + shape(unary.getArg()) + "]";
		}
		return order(expr);
	}

	private static String order(TupleExpr expr) {
		if (expr instanceof StatementPattern pattern) {
			return pattern.getPredicateVar().getValue().stringValue().substring("urn:".length());
		}
		if (expr instanceof BinaryTupleOperator binary) {
			return expr.getClass().getSimpleName() + "(" + order(binary.getLeftArg()) + ","
					+ order(binary.getRightArg()) + ")";
		}
		if (expr instanceof UnaryTupleOperator unary) {
			return expr.getClass().getSimpleName() + "[" + order(unary.getArg()) + "]";
		}
		return expr.getClass().getSimpleName();
	}

	private static StatementPattern sp(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of("_const_" + predicate.substring(4), VF.createIRI(
				predicate), false, true), Var.of(object));
	}

	private static final class OpaqueTuple extends UnaryTupleOperator {

		private static final long serialVersionUID = 1L;

		private OpaqueTuple(TupleExpr argument) {
			super(argument);
		}

		@Override
		public <X extends Exception> void visit(QueryModelVisitor<X> visitor) throws X {
			visitor.meetOther(this);
		}
	}
}
